"""Conteúdo editorial da CC-11: Código Civil, arts. 1.041–1.162."""

def row(diz, significa, exemplo, atencao, termo, definicao):
    return {"target": None, "o_que_diz": diz, "o_que_significa": significa,
            "exemplo_pratico": exemplo, "atencao": atencao,
            "palavras_dificeis": [{"termo": termo, "explicacao": definicao}]}

ROWS = {
"1041": row("O contrato da sociedade em nome coletivo deve conter as informações gerais do art. 997 e indicar a firma social.","Além das cláusulas comuns, é necessário identificar o nome empresarial sob o qual a sociedade atuará.","Dois sócios constituem sociedade e registram no contrato a firma que usarão perante clientes.","A firma deve observar as regras do nome empresarial e não substitui as demais cláusulas obrigatórias.","Firma social","nome empresarial formado segundo as regras aplicáveis aos sócios"),
"1042": row("Somente sócios podem administrar a sociedade em nome coletivo; apenas administradores autorizados usam a firma dentro do contrato.","A gestão e a vinculação pelo nome empresarial ficam reservadas aos sócios que receberam poderes.","Sócio sem poderes não assina contrato em nome da sociedade.","Atos fora dos poderes podem gerar responsabilidade e controvérsia sobre vinculação perante terceiros.","Uso da firma","emprego do nome empresarial para assumir obrigações"),
"1043": row("Antes da dissolução, credor pessoal de sócio não liquida sua quota, salvo prorrogação tácita ou oposição judicial acolhida à prorrogação contratual, apresentada em noventa dias da publicação.","O patrimônio social é preservado, mas a prorrogação pode abrir ao credor a via excepcional de liquidação da participação do devedor.","Credor se opõe judicialmente, no prazo, à extensão formal da sociedade.","A hipótese depende do tipo de prorrogação e, na contratual, de decisão judicial favorável e prazo contado da publicação.","Liquidação da quota","apuração e pagamento do valor da participação societária"),
"1044": row("A sociedade em nome coletivo dissolve-se pelas causas do art. 1.033 e, se empresária, também pela falência.","Às causas gerais de dissolução soma-se a quebra quando a sociedade exerce atividade empresária.","Sociedade empresária em nome coletivo tem a falência decretada e entra em dissolução.","Dissolução não dispensa liquidação e extinção registral conforme o procedimento aplicável.","Dissolução de pleno direito","ocorrência legal que desencadeia o encerramento societário"),
"1045": row("A comandita simples reúne comanditados, pessoas físicas com responsabilidade solidária e ilimitada, e comanditários, limitados à quota; o contrato deve distingui-los.","As duas categorias assumem riscos e funções diferentes, que precisam estar expressas no ato constitutivo.","Contrato identifica Ana como comanditada e Bruno como comanditário de quota definida.","Limitação do comanditário não protege comanditado nem dispensa integralização da quota.","Comanditado","sócio que responde solidária e ilimitadamente pelas obrigações sociais"),
"1046": row("Regras da sociedade em nome coletivo completam a comandita simples quando compatíveis; comanditados têm os direitos e deveres daquele tipo.","A disciplina subsidiária vale sem apagar a divisão entre comanditados e comanditários.","Lacuna sobre administração é resolvida por norma compatível da sociedade em nome coletivo.","A compatibilidade deve ser examinada antes da aplicação subsidiária.","Aplicação subsidiária","uso complementar de outro regime para suprir lacuna compatível"),
"1047": row("O comanditário pode deliberar e fiscalizar, mas não gerir nem integrar a firma; pode ser procurador para negócio determinado, com poderes especiais.","A interferência regular é permitida, enquanto gestão ou uso do nome pode fazê-lo responder como comanditado.","Comanditário recebe procuração específica para assinar uma compra, sem assumir administração geral.","Procuração genérica ou atuação habitual pode ultrapassar a exceção e ampliar sua responsabilidade.","Ato de gestão","decisão ou operação própria da administração da sociedade"),
"1048": row("Redução da quota do comanditário só alcança terceiros após averbação da alteração contratual e não prejudica credores anteriores.","A publicidade registral marca a eficácia externa, preservando créditos formados antes da redução.","Redução é assinada hoje, mas só passa a ser oposta a fornecedor após registro.","A averbação não elimina a proteção dos credores preexistentes.","Averbação","anotação registral de alteração relacionada a ato já inscrito"),
"1049": row("Comanditário não repõe lucro recebido de boa-fé conforme balanço; havendo perda posterior do capital, não recebe novos lucros antes de sua recomposição.","O recebimento regular é protegido, mas a preservação do capital impede distribuição enquanto a perda não for coberta.","Sócio conserva dividendo regular, porém aguarda recomposição do capital para nova distribuição.","Boa-fé e conformidade do balanço são indispensáveis; distribuição irregular segue outro regime.","Reintegração do capital","recomposição do capital reduzido por perdas"),
"1050": row("Morrendo comanditário, a sociedade continua com os sucessores, salvo cláusula diversa; eles escolhem representante.","A sucessão não dissolve automaticamente a sociedade nem impõe atuação fragmentada dos herdeiros.","Herdeiros indicam uma pessoa para exercer os direitos ligados à quota herdada.","O contrato pode estabelecer solução diferente para a morte do comanditário.","Sucessores","pessoas que recebem direitos e deveres transmissíveis do falecido"),
"1051": row("A comandita dissolve-se pelas causas do art. 1.044 ou se faltar uma categoria de sócio por mais de 180 dias; sem comanditado, cabe administrador provisório, que não vira sócio.","A estrutura de duas categorias deve ser recomposta no semestre, com gestão temporária limitada à continuidade.","Último comanditado sai e os comanditários nomeiam gestor enquanto buscam substituto.","O administrador provisório não assume por isso responsabilidade de comanditado, mas o prazo deve ser observado.","Administrador provisório","gestor temporário nomeado para manter a administração durante a falta de comanditado"),
"1052": row("Na limitada, cada sócio responde até suas quotas, todos garantem solidariamente a integralização; ela pode ter um único sócio.","A limitação convive com responsabilidade conjunta pelo capital prometido e admite sociedade limitada unipessoal.","Sócio único constitui limitada; em sociedade plural, credor cobra integralização ainda faltante.","Limitação não encobre fraude, abuso nem elimina deveres pessoais de administradores.","Integralização","entrega efetiva dos valores ou bens prometidos ao capital"),
"1053": row("O regime da sociedade simples supre omissões da limitada, mas o contrato pode escolher normas das sociedades anônimas como disciplina supletiva.","A fonte subsidiária depende do contrato, sem transformar a limitada em companhia.","Contrato prevê aplicação supletiva da lei das sociedades anônimas a tema omisso compatível.","Norma especial e regra expressa da limitada prevalecem sobre a disciplina supletiva.","Regência supletiva","conjunto de normas escolhido para completar lacunas do regime principal"),
"1054": row("O contrato da limitada deve trazer, quando cabíveis, as indicações do art. 997 e a firma social, se adotada.","O ato constitutivo combina requisitos gerais com a identificação empresarial escolhida.","Sócios registram capital, quotas, administração e firma no contrato.","As indicações são aplicadas conforme a natureza da limitada e demais leis registrais.","Ato constitutivo","documento que cria e organiza a sociedade"),
"1055": row("O capital divide-se em quotas iguais ou desiguais; sócios respondem por cinco anos pela avaliação de bens aportados, e serviços não podem integralizar quotas.","Há liberdade na distribuição das quotas, mas avaliação inflada gera responsabilidade solidária temporária.","Imóvel superavaliado no capital permite responsabilizar os sócios dentro do quinquênio registral.","Trabalho pode ser contratado, mas não serve como contribuição ao capital da limitada.","Quota social","fração do capital e da posição do sócio"),
"1056": row("A quota é indivisível perante a sociedade, salvo transferência; em condomínio, direitos são exercidos por representante ou inventariante, e condôminos respondem pela integralização.","Vários titulares não fragmentam a relação societária e devem atuar por voz comum.","Herdeiros de uma quota designam representante para votar.","A solidariedade pela integralização permanece sem afastar a regra geral do art. 1.052.","Condomínio de quota","cotitularidade de uma mesma participação societária"),
"1057": row("Sem cláusula diversa, quota pode ser cedida livremente a sócio; a estranho, se titulares de mais de um quarto do capital não se opuserem. Eficácia externa exige averbação.","O contrato pode regular a circulação; no silêncio, a entrada de terceiro sofre controle minoritário e publicidade registral.","Sócio vende quota a terceiro após não surgir oposição suficiente e registra a cessão.","A assinatura dos anuentes e a averbação são essenciais para efeitos perante sociedade e terceiros.","Cessão de quota","transferência total ou parcial da participação societária"),
"1058": row("Se sócio não integraliza a quota, os demais podem tomá-la ou transferi-la a terceiro, excluindo o remisso e devolvendo o pago com descontos de mora, prestações e despesas.","A sociedade pode substituir o inadimplente e preservar o capital, apurando o saldo que lhe será restituído.","Sócio deixa de aportar parcela e sua quota é assumida pelos demais, com descontos legais.","A medida não exclui outras consequências previstas no art. 1.004 e no contrato.","Sócio remisso","sócio em atraso com a contribuição prometida ao capital"),
"1059": row("Sócios devem devolver lucros ou retiradas distribuídos com prejuízo do capital, mesmo quando o contrato os autorizava.","O capital não pode ser consumido por distribuição interna disfarçada de lucro.","Balanço revela que retirada autorizada reduziu capital; beneficiários repõem valores.","Autorização contratual não valida distribuição incompatível com a preservação do capital.","Reposição","devolução à sociedade de valor indevidamente retirado"),
"1060": row("A limitada é administrada por uma ou mais pessoas nomeadas no contrato ou em ato separado; cláusula que nomeia todos os sócios não alcança automaticamente futuros sócios.","A investidura depende de designação, não apenas da aquisição posterior de quota.","Comprador de quota não vira administrador por cláusula antiga dirigida aos sócios originários.","Poderes, impedimentos e publicidade da nomeação também precisam ser observados.","Ato separado","documento societário distinto do contrato que formaliza a nomeação"),
"1061": row("Administrador não sócio exige votos de ao menos dois terços do quadro social até a integralização do capital; depois, basta a aprovação de quotas superiores à metade do capital.","A Lei 14.451/2022 reduziu os quóruns e diferencia a fase anterior e posterior à integralização.","Com capital completo, titulares de 60% aprovam administradora externa.","Não use os antigos quóruns de unanimidade ou dois terços após a integralização.","Quórum de aprovação","proporção mínima exigida para uma decisão válida"),
"1062": row("Administrador nomeado em ato separado toma posse no livro próprio em 30 dias e requer averbação em 10 dias da investidura, com seus dados e prazo de gestão.","Designação, posse tempestiva e publicidade registral formam etapas distintas.","Nomeado assina termo no vigésimo dia e protocola sua averbação dentro dos dez dias seguintes.","Sem assinatura em trinta dias, a nomeação perde efeito; o segundo prazo conta da investidura.","Termo de posse","registro formal pelo qual o nomeado aceita e assume o cargo"),
"1063": row("Administração termina por destituição ou fim do prazo sem recondução; destituir sócio nomeado no contrato exige mais da metade do capital, salvo cláusula diversa, e a cessação deve ser registrada.","A saída pode ocorrer a qualquer tempo, mas há quórum atual e deveres de publicidade.","Titulares de 55% destituem administrador-sócio quando o contrato não altera o critério.","A redação vigente não exige dois terços; renúncia também demanda comunicação e averbação.","Recondução","renovação da pessoa no cargo após o término do mandato"),
"1064": row("Somente administradores com poderes podem usar a firma ou denominação da sociedade.","O nome empresarial vincula a limitada quando empregado por gestor autorizado.","Gerente sem poder societário não assina pela firma como administrador.","É preciso verificar o contrato, a nomeação e limitações oponíveis a terceiros.","Denominação social","nome empresarial formado sem necessidade de usar nome de sócio"),
"1065": row("Ao fim de cada exercício, devem ser preparados inventário, balanço patrimonial e balanço de resultado econômico.","A administração deve apurar periodicamente bens, obrigações, patrimônio e desempenho.","No encerramento anual, a limitada elabora demonstrações para apreciação dos sócios.","A obrigação convive com normas contábeis e legislação especial aplicável.","Balanço patrimonial","demonstração da posição de ativos, passivos e patrimônio"),
"1066": row("O contrato pode criar conselho fiscal com ao menos três membros e suplentes, sócios ou não, residentes no país; a lei define impedimentos e assegura eleição separada à minoria qualificada.","O órgão é facultativo, mas sua composição deve preservar independência e representação minoritária.","Contrato cria conselho de três membros e sócios minoritários elegem um deles separadamente.","Administradores, empregados e parentes indicados na lei não podem integrar o conselho.","Conselho fiscal","órgão societário que fiscaliza administração e contas"),
"1067": row("Conselheiro ou suplente eleito toma posse por termo no livro e atua até a assembleia anual seguinte, salvo cessação anterior; sem assinatura em 30 dias, a eleição perde efeito.","A investidura formal e tempestiva condiciona o exercício da fiscalização.","Conselheiro assina o termo com seus dados dentro do prazo.","Eleição não basta sem posse no livro próprio.","Suplente","pessoa eleita para substituir membro titular quando necessário"),
"1068": row("A assembleia que elege o conselho fiscal fixa anualmente a remuneração de seus membros.","O pagamento é decisão periódica dos sócios, não unilateral dos próprios fiscais.","Na assembleia anual, sócios elegem conselheiros e definem remuneração para o mandato.","Devem ser respeitados contrato, conflito de interesses e regularidade da deliberação.","Remuneração anual","valor definido para o período de exercício da função"),
"1069": row("Conselheiros fiscalizam livros, caixa e contas trimestralmente, registram exames, opinam sobre demonstrações e operações, denunciam irregularidades e convocam assembleia nas hipóteses legais.","A fiscalização é contínua, documentada e inclui reação a erros, fraudes e urgências.","Conselheiro detecta desvio, registra conclusão e convoca reunião extraordinária se a administração se omite.","As atribuições podem ser individuais ou colegiadas conforme o inciso; prazos e relatórios devem ser observados.","Parecer fiscal","manifestação técnica do conselho sobre contas e atos societários"),
"1070": row("Poderes legais do conselho fiscal não podem ser transferidos a outro órgão; seus membros respondem como administradores e podem contratar contabilista habilitado com remuneração aprovada.","A função é indelegável, embora assistência técnica seja permitida sem deslocar a responsabilidade.","Conselho contrata contador para examinar balanços, mas mantém sua própria conclusão.","Auxílio técnico não exonera o conselheiro de diligência e responsabilidade.","Indelegabilidade","impossibilidade de transferir a terceiro a função legal atribuída"),
"1071": row("Contas, administradores, remuneração, contrato, reorganizações, liquidação e recuperação dependem de deliberação dos sócios, além de outras matérias legais ou contratuais.","Decisões estruturais e de controle não ficam ao arbítrio isolado da administração.","Sócios votam alteração contratual e escolha de novo administrador.","Cada matéria segue o quórum vigente do art. 1.076 ou regra especial.","Deliberação societária","decisão coletiva tomada pelos sócios segundo forma e quórum"),
"1072": row("Decisões ocorrem em reunião ou assembleia convocada; assembleia é obrigatória com mais de dez sócios, mas unanimidade escrita dispensa encontro, e todos presentes dispensam formalidade de convocação.","A lei combina procedimento formal com simplificações quando todos têm ciência ou concordam por escrito.","Todos os sócios assinam decisão escrita e dispensam assembleia.","Dispensa de encontro não elimina quórum material, documentação nem registro quando exigido.","Deliberação escrita","decisão unânime documentada sem reunião presencial"),
"1073": row("Sócio pode convocar se administradores atrasarem mais de 60 dias ou se titulares de mais de um quinto não forem atendidos em oito dias; conselho fiscal também convoca nas hipóteses legais.","A omissão administrativa não paralisa o órgão deliberativo.","Sócios de 25% pedem reunião fundamentada e a convocam após oito dias sem resposta.","Os dois fundamentos de convocação por sócio têm requisitos e prazos distintos.","Convocação subsidiária","chamamento feito por legitimado quando o responsável principal se omite"),
"1074": row("Assembleia instala-se na primeira chamada com três quartos do capital e, na segunda, com qualquer número; sócio pode ser representado por sócio ou advogado com mandato específico e não vota assunto próprio.","Quórum de instalação difere do quórum da decisão, e conflito pessoal impede o voto.","Na segunda convocação, poucos sócios iniciam a assembleia, mas ainda observam a maioria exigida para a matéria.","Representação deve indicar atos autorizados e o instrumento acompanha a ata.","Quórum de instalação","presença mínima para abrir validamente a assembleia"),
"1075": row("Sócios presentes escolhem presidente e secretário; a ata é assinada pela mesa e participantes suficientes, e cópia autenticada vai ao registro em vinte dias.","A deliberação precisa ser documentada e publicizada no prazo legal.","Mesa lavra ata, obtém assinaturas necessárias e protocola cópia na Junta Comercial.","Sócios que desejarem podem assinar, mesmo além do número suficiente à validade.","Mesa da assembleia","presidente e secretário responsáveis pela condução e documentação"),
"1076": row("Salvo a nomeação do art. 1.061, matérias estruturais indicadas exigem mais da metade do capital; os demais casos, maioria dos presentes, salvo exigência legal ou contratual maior.","A Lei 14.451/2022 revogou o inciso I e atualizou os quóruns da limitada.","Titulares de 55% aprovam alteração contratual abrangida pelo inciso II vigente.","Não aplicar quóruns anteriores; identifique a matéria e eventual regra especial ou contratual mais severa.","Maioria do capital","votos ligados a mais de cinquenta por cento do capital social"),
"1077": row("Dissidente de alteração contratual, fusão ou incorporação pode retirar-se em trinta dias da reunião, com apuração conforme contrato ou art. 1.031.","A discordância qualificada permite romper o vínculo e receber haveres.","Sócio vota contra fusão e comunica retirada dentro de trinta dias.","O direito depende das operações enumeradas e do prazo; cálculo dos haveres segue disciplina própria.","Direito de retirada","faculdade de sair da sociedade diante de decisão relevante"),
"1078": row("A assembleia anual ocorre nos quatro meses após o exercício para contas, balanços, administradores e pauta; documentos ficam disponíveis 30 dias antes, e aprovação sem erro exonera gestores, salvo fraude.","Os sócios recebem informação prévia e exercem controle anual sobre administração.","Empresa encerra exercício em dezembro e reúne sócios até abril com balanços acessíveis desde março.","Erro, dolo ou simulação impedem exoneração; anulação da aprovação tem prazo legal de dois anos.","Prestação de contas","apresentação documentada da gestão e de seus resultados"),
"1079": row("Quando o contrato não disciplinar reunião de sócios, aplicam-se as regras legais da assembleia, respeitada a obrigatoriedade para sociedades com mais de dez sócios.","O regime da assembleia preenche lacunas procedimentais das reuniões.","Contrato omite forma de votação e a reunião segue subsidiariamente a seção legal.","Regra contratual válida prevalece onde a lei permite, sem afastar exigências obrigatórias.","Regra subsidiária","norma aplicada apenas quando falta disciplina principal"),
"1080": row("Quem aprova expressamente deliberação contrária à lei ou ao contrato passa a responder ilimitadamente por ela.","A proteção da limitada não cobre adesão consciente e expressa a decisão ilícita.","Sócios aprovam distribuição ilegal e os votantes favoráveis respondem sem o limite das quotas.","A sanção alcança os aprovadores expressos, exigindo identificar voto e infração.","Responsabilidade ilimitada","dever de responder sem teto correspondente à quota"),
"1080-A": row("Sócio pode participar e votar a distância; reunião ou assembleia pode ser digital se preservar voz, debate, voto e requisitos regulamentares.","A presença eletrônica tem validade jurídica quando garante participação efetiva.","Sócio entra por plataforma, debate e registra seu voto remotamente.","Tecnologia não autoriza restringir direitos nem dispensar convocação, identificação e documentação.","Assembleia digital","deliberação societária realizada por meios eletrônicos"),
"1081": row("Com quotas integralizadas, o capital pode aumentar por alteração contratual; sócios têm preferência proporcional por 30 dias, e a operação é formalizada após subscrição total.","O aumento protege a proporção dos atuais sócios antes da entrada de novos recursos ou terceiros.","Sócio exerce preferência dentro de trinta dias para evitar diluição.","Lei especial, cessão da preferência e registro da alteração também devem ser considerados.","Direito de preferência","prioridade do sócio para participar do aumento de capital"),
"1082": row("A limitada pode reduzir capital integralizado por perdas irreparáveis ou quando ele for excessivo ao objeto, mediante alteração contratual.","A redução tem fundamentos fechados e não é simples retirada livre de patrimônio.","Após perdas definitivas, sócios ajustam o capital ao patrimônio real.","Cada fundamento segue procedimento próprio nos artigos seguintes e protege credores.","Redução de capital","diminuição formal do valor do capital social"),
"1083": row("Na redução por perdas, diminui-se proporcionalmente o valor nominal das quotas, com eficácia a partir da averbação da ata aprovada.","O ajuste contábil e societário só se completa externamente com o registro.","Quotas de todos têm valor nominal reduzido na mesma proporção e a ata é averbada.","Esta regra trata de perdas irreparáveis, não da devolução por capital excessivo.","Valor nominal","valor atribuído à quota no capital social"),
"1084": row("Se o capital for excessivo, reduz-se devolvendo valores ou dispensando aportes; credor quirografário anterior pode opor-se em 90 dias, e eficácia depende de pagamento, depósito ou ausência de oposição.","A proteção do credor antecede a retirada de recursos pelos sócios.","Credor sem garantia contesta redução e a sociedade deposita o valor discutido.","Publicação, anterioridade e liquidez do crédito condicionam a oposição.","Credor quirografário","credor sem garantia real ou preferência específica"),
"1085": row("Maioria representando mais da metade do capital pode excluir sócio por atos graves que ameacem a empresa, se o contrato prever justa causa; em regra há reunião específica e defesa, dispensada na sociedade de dois sócios.","A exclusão extrajudicial exige previsão, gravidade, maioria qualificada e procedimento defensivo, com exceção legal para dois sócios.","Sócios majoritários convocam reunião exclusiva e permitem defesa antes de excluir autor de fraude grave.","Não basta desavença; verifique continuidade ameaçada, cláusula contratual e forma vigente.","Exclusão por justa causa","retirada compulsória de sócio por falta grave prevista no contrato"),
"1086": row("Registrada a alteração que exclui o sócio, aplicam-se as regras de liquidação da quota e de responsabilidade por obrigações anteriores e posteriores.","A saída exige apuração de haveres e mantém responsabilidades temporais definidas nos arts. 1.031 e 1.032.","Após registrar exclusão, sociedade levanta balanço especial e apura a quota.","O registro é relevante para eficácia e contagem dos períodos de responsabilidade.","Apuração de haveres","cálculo do valor devido ao sócio que deixa a sociedade"),
"1087": row("A limitada dissolve-se pelas causas legais aplicáveis à sociedade em nome coletivo.","O art. 1.044 remete às causas gerais e, para empresária, à falência.","Fim do prazo sem continuidade válida desencadeia dissolução da limitada.","Depois da causa dissolutória ainda são necessários liquidação e registro da extinção.","Causa dissolutória","fato que inicia o encerramento jurídico da sociedade"),
"1088": row("Na sociedade anônima, capital é dividido em ações e acionista responde apenas pelo preço de emissão das ações subscritas ou adquiridas.","A exposição patrimonial ordinária limita-se ao compromisso de pagar as ações.","Acionista integraliza ações pelo preço de emissão sem responder automaticamente por dívida da companhia.","Abuso, dever pessoal ou regra especial pode gerar responsabilidade própria.","Preço de emissão","valor pelo qual a ação é emitida e assumida pelo acionista"),
"1089": row("A sociedade anônima segue sua lei especial; o Código Civil só completa omissões.","A Lei das Sociedades por Ações é a disciplina principal.","Questão de assembleia da companhia é resolvida primeiro pela legislação especial.","Não transponha automaticamente regras da limitada para a companhia.","Lei especial","diploma que regula especificamente determinada matéria ou tipo societário"),
"1090": row("A comandita por ações tem capital em ações, aplica normas da sociedade anônima com adaptações próprias e usa firma ou denominação.","É tipo acionário com regime especial de administração e responsabilidade.","Companhia em comandita emite ações, mas observa as regras específicas dos diretores.","As modificações deste capítulo prevalecem sobre normas gerais incompatíveis da companhia.","Comandita por ações","sociedade acionária cujos diretores assumem responsabilidade especial"),
"1091": row("Somente acionista pode administrar a comandita por ações e, como diretor, responde subsidiária e ilimitadamente; vários diretores respondem solidariamente após os bens sociais, têm mandato sem prazo e destituição por dois terços.","Diretor acumula posição acionária e risco pessoal ampliado, inclusive por obrigações posteriores por período legal.","Após insuficiência patrimonial, credor alcança diretores responsáveis; destituição requer dois terços do capital.","A responsabilidade é subsidiária e há regra temporal de dois anos para ex-diretor.","Responsabilidade subsidiária","cobrança pessoal após insuficiência do devedor principal"),
"1092": row("Assembleia da comandita por ações precisa do consentimento dos diretores para mudar objeto essencial, duração, capital ou criar debêntures e partes beneficiárias.","Decisões estruturais dependem de concordância da administração pessoalmente responsável.","Acionistas aprovam aumento de capital, mas a medida exige anuência dos diretores.","A exigência é específica deste tipo e não se confunde com quórum comum de companhia.","Parte beneficiária","título que pode atribuir participação em lucros sem representar ação"),
"1093": row("Cooperativa segue este capítulo, preservada a legislação especial.","O Código Civil atua junto da lei cooperativista, que prevalece nas regras específicas.","Constituição de cooperativa consulta o Código e a Lei 5.764/1971.","A solução exige verificar legislação especial vigente e regulação setorial.","Legislação cooperativista","normas especiais aplicáveis às sociedades cooperativas"),
"1094": row("Cooperativa pode ter capital variável ou dispensá-lo, número aberto de sócios, quotas limitadas e intransferíveis a estranhos, voto pessoal, retorno proporcional e indivisibilidade de fundos legais.","Sua organização privilegia pessoas e atividade comum, não concentração de capital.","Cada cooperado vota uma vez, ainda que possua mais quotas.","As características convivem com exceções e detalhamento da legislação especial.","Retorno","distribuição de sobras conforme operações do cooperado"),
"1095": row("A responsabilidade do cooperado pode ser limitada à quota e aos prejuízos proporcionais, ou ilimitada pelas obrigações sociais.","O ato constitutivo e a lei definem o alcance do risco patrimonial dos membros.","Cooperativa limitada cobra do cooperado apenas quota e perdas na proporção legal.","Não presuma limitação: é necessário identificar o regime adotado e a lei especial.","Responsabilidade do cooperado","alcance patrimonial dos deveres do membro da cooperativa"),
"1096": row("Nas omissões, aplicam-se à cooperativa regras da sociedade simples compatíveis com sua natureza.","A integração subsidiária não elimina princípios cooperativos.","Lacuna sobre administração recebe regra da sociedade simples que não conflite com a lei cooperativa.","Compatibilidade com a estrutura cooperativista é requisito indispensável.","Natureza cooperativa","características próprias da organização voltada à atividade comum dos membros"),
"1097": row("Sociedades consideram-se coligadas quando sua participação recíproca se enquadra nas relações definidas nos artigos seguintes.","Coligação é categoria legal baseada na influência e participação entre sociedades.","Empresa possui participação relevante em outra e a relação é classificada segundo a lei.","O rótulo depende dos critérios específicos, não de mera relação comercial.","Sociedades coligadas","sociedades ligadas por participação ou influência juridicamente relevante"),
"1098": row("É controlada a sociedade cujo capital outra detenha votos suficientes para formar maioria e eleger a maior parte dos administradores; controladora é quem exerce esse poder direta ou indiretamente.","Controle decorre de poder decisório estável, inclusive por cadeia societária.","Holding domina votos e eleição da administração de subsidiária.","Participação econômica sem poder de voto suficiente pode não configurar controle.","Controle societário","poder de dirigir deliberações e escolher administradores"),
"1099": row("Coligada ou filiada é a sociedade de cujo capital outra participa com dez por cento ou mais sem controlá-la.","Participação relevante inferior ao controle cria vínculo legal de coligação.","Empresa detém 15% de outra, mas não domina votos, caracterizando coligação.","Devem ser considerados direitos de voto e eventual controle indireto.","Participação relevante","percentual societário suficiente para produzir classificação legal"),
"1100": row("Há simples participação quando uma sociedade possui menos de dez por cento do capital votante de outra, sem controlá-la.","A lei distingue investimento minoritário simples de coligação e controle.","Companhia compra 6% das ações votantes de outra sem influência dominante.","A qualificação considera capital com voto e ausência de controle.","Simples participação","investimento societário abaixo do limiar de coligação"),
"1101": row("Salvo regra especial, sociedade não participa de outra acima do valor de suas próprias reservas, excluída a reserva legal; excesso deve ser alienado em 180 dias da aprovação do balanço que o revelou.","A limitação protege o capital da investidora e impõe correção tempestiva do excesso.","Balanço aponta investimento superior às reservas disponíveis e a sociedade vende o excedente em seis meses.","Legislação especial pode afastar o limite; cálculo e termo inicial exigem balanço aprovado.","Reservas livres","parcelas patrimoniais disponíveis consideradas no limite de participação"),
"1102": row("Dissolvida a sociedade e subsistindo personalidade para liquidar, administradores devem investir liquidante e restringir-se a negócios inadiáveis, identificando o estado de liquidação nos atos.","A atividade muda de exploração para encerramento ordenado e preservação patrimonial.","Após dissolução, gestor evita novo empreendimento e acrescenta 'em liquidação' ao nome.","Nova operação indevida pode gerar responsabilidade solidária e ilimitada do administrador.","Estado de liquidação","fase de realização do ativo, pagamento do passivo e partilha"),
"1103": row("Se o contrato não indicar liquidante, os sócios o escolhem, podendo ser terceiro; a qualquer tempo podem destituí-lo, e judicialmente exige justa causa.","A liquidação pode ser conduzida por pessoa externa, sujeita a substituição conforme a via usada.","Sócios elegem contador como liquidante e depois o substituem por deliberação.","Destituição judicial depende de motivo justificado, diferentemente da deliberação societária.","Liquidante","responsável por conduzir o encerramento patrimonial da sociedade"),
"1104": row("Liquidante deve averbar e publicar sua nomeação, arrecadar bens, levantar inventário e balanço, concluir negócios, cobrar créditos, pagar dívidas, vender bens, prestar contas e convocar sócios.","Suas tarefas abrangem publicidade, apuração patrimonial, realização do ativo e transparência periódica.","Liquidante registra nomeação, cobra clientes, vende estoque e apresenta balanço anual.","Atos devem servir à liquidação; responsabilidades seguem regras dos administradores.","Realização do ativo","conversão dos bens e créditos sociais em recursos para pagar obrigações"),
"1105": row("Liquidante representa a sociedade e pratica atos necessários, mas só onera bens, toma empréstimos não urgentes ou continua atividade com autorização contratual ou da maioria.","Poderes ordinários são amplos para encerrar; atos extraordinários exigem autorização, salvo empréstimo indispensável a obrigação inadiável.","Liquidante vende imóvel para pagar dívida, mas pede autorização para hipotecá-lo.","A continuidade da empresa deve facilitar a liquidação e não reabrir a atividade normal.","Ônus real","garantia ou direito que grava diretamente um bem"),
"1106": row("Respeitadas preferências, liquidante paga credores proporcionalmente, inclusive dívidas vincendas com desconto; se o ativo superar o passivo, pode pagar vencidas integralmente sob responsabilidade pessoal.","A igualdade entre credores comuns orienta o pagamento, evitando favorecimento indevido.","Recursos insuficientes são rateados proporcionalmente depois dos credores preferenciais.","Pagamento integral antecipado pelo liquidante exige segurança de superávit e o expõe pessoalmente.","Dívida vincenda","obrigação cujo vencimento ainda ocorrerá"),
"1107": row("Depois de pagos os credores e antes do fim da liquidação, maioria dos sócios pode autorizar rateios antecipados conforme os haveres apurados.","Sobras podem ser distribuídas gradualmente sem comprometer o passivo já satisfeito.","Liquidante reparte parte do remanescente após deliberação majoritária.","A antecipação só ocorre depois do pagamento dos credores e conforme apuração segura.","Rateio antecipado","distribuição parcial antes da partilha final"),
"1108": row("Pago o passivo e dividido o remanescente, liquidante convoca assembleia para prestar contas finais.","A conclusão material deve ser submetida ao controle dos sócios.","Após vender bens e pagar dívidas, liquidante apresenta relatório e documentos finais.","A prestação de contas precede encerramento formal e extinção registral.","Passivo","conjunto de dívidas e obrigações da sociedade"),
"1109": row("Aprovadas as contas, liquidação termina e sociedade extingue-se com averbação da ata; dissidente pode agir em 30 dias da publicação da ata averbada.","A extinção exige deliberação, publicidade e registro, preservando prazo curto de impugnação.","Ata final é averbada e publicada; sócio dissidente ajuíza medida dentro do mês.","O prazo conta da publicação da ata devidamente averbada.","Extinção registral","fim da pessoa jurídica formalizado no registro competente"),
"1110": row("Após a liquidação, credor não pago cobra de cada sócio até o que recebeu na partilha e pode exigir perdas e danos do liquidante.","A cobrança pós-extinção limita o sócio ao benefício recebido, sem proteger liquidante faltoso.","Credor cobra de sócio o montante que ele recebeu e processa liquidante negligente pelo restante danoso.","A responsabilidade do liquidante exige fundamento de perdas e danos; limites são individualizados.","Partilha","distribuição do patrimônio remanescente entre os sócios"),
"1111": row("Liquidação judicial segue a legislação processual.","O Código remete rito, atos e controle ao processo judicial aplicável.","Juízo conduz a liquidação conforme regras processuais vigentes.","Não se deve completar o rito apenas com regras da liquidação extrajudicial.","Liquidação judicial","encerramento patrimonial conduzido sob direção do Judiciário"),
"1112": row("Na liquidação judicial, juiz pode convocar e presidir reunião ou assembleia, decidir sumariamente questões surgidas e juntar atas autênticas ao processo.","O juízo coordena deliberações necessárias à solução eficiente da liquidação.","Juiz reúne sócios para decidir venda relevante e anexa a ata aos autos.","Decisão sumária no incidente não elimina garantias processuais aplicáveis.","Autos","conjunto de documentos e atos que formam o processo"),
"1113": row("Transformação muda o tipo societário sem dissolução ou liquidação e deve cumprir constituição e registro do novo tipo.","A mesma pessoa jurídica continua, adaptando sua organização ao modelo escolhido.","Limitada transforma-se em sociedade anônima sem repartir previamente o patrimônio.","Devem ser satisfeitos todos os requisitos do tipo de destino.","Transformação societária","mudança do tipo jurídico com continuidade da sociedade"),
"1114": row("Transformação exige unanimidade, salvo autorização prévia no ato constitutivo; nesse caso, dissidente pode retirar-se e apurar haveres.","A cláusula antecipada substitui unanimidade, mas protege quem discorda com direito de saída.","Contrato autoriza transformação por maioria e sócio contrário exerce retirada.","A apuração segue estatuto, contrato ou, no silêncio, art. 1.031.","Consentimento unânime","aprovação de todos os sócios"),
"1115": row("Transformação não prejudica credores; eventual falência alcança sócios sujeitos no tipo anterior apenas a pedido de credores anteriores e em benefício deles.","A mudança não pode apagar garantias ou responsabilidades já formadas.","Credor anterior pede que falência preserve responsabilidade ilimitada existente antes da transformação.","A extensão excepcional depende de pedido e favorece somente créditos anteriores.","Credor anterior","titular de crédito existente antes da transformação"),
"1116": row("Incorporação ocorre quando uma ou mais sociedades são absorvidas por outra, que sucede todos os direitos e obrigações, mediante aprovação conforme cada tipo.","A incorporadora permanece e assume universalmente posições das incorporadas, que serão extintas.","Empresa A absorve B e passa a responder por seus contratos e dívidas.","A operação exige deliberações e formalidades próprias de todas as sociedades envolvidas.","Sucessão universal","transferência global de direitos e obrigações"),
"1117": row("Sócios aprovam bases da incorporação, reforma do ato, autorização aos administradores e nomeação de peritos para avaliar patrimônio líquido da incorporada.","A operação combina decisão informada e avaliação técnica antes da absorção.","Incorporadora nomeia peritos, analisa laudo e ajusta seu contrato para receber patrimônio.","Administradores não votam por sociedade incorporada sem a aprovação societária prevista.","Patrimônio líquido","diferença entre ativos e passivos avaliados"),
"1118": row("Aprovados os atos, incorporadora declara extinta a incorporada e averba a operação no registro.","A extinção e sucessão precisam de formalização registral.","Após laudos e deliberações, incorporadora protocola atos e baixa a incorporada.","A declaração pressupõe cumprimento das etapas anteriores da incorporação.","Averbação da incorporação","registro que publiciza absorção e extinção da incorporada"),
"1119": row("Fusão extingue as sociedades unidas e cria nova sociedade que as sucede em direitos e obrigações.","Diferentemente da incorporação, nenhuma das sociedades originais permanece.","A e B se extinguem para formar C, que assume contratos e dívidas.","A nova sociedade deve ser regularmente constituída e registrada.","Fusão","união de sociedades com extinção das anteriores e criação de nova"),
"1120": row("Cada sociedade decide a fusão segundo seu tipo, aprova projeto e distribuição do capital, nomeia peritos e delibera sobre laudos sem votar avaliação do próprio patrimônio.","Avaliação cruzada e decisões separadas reduzem conflito de interesses.","Sócios de A não votam o laudo de A, mas participam das demais decisões da operação.","Laudos e projeto devem ser aprovados antes da constituição definitiva da nova sociedade.","Laudo de avaliação","relatório técnico sobre o valor do patrimônio"),
"1121": row("Constituída a sociedade resultante da fusão, seus administradores registram na sede os atos da operação.","A nova administração assume a publicidade e regularização do negócio.","Diretores de C arquivam atas, laudos e ato constitutivo no registro competente.","A inscrição é necessária para eficácia e regularidade perante terceiros.","Registro da fusão","arquivamento dos documentos que formalizam a operação"),
"1122": row("Credor anterior prejudicado pode pedir anulação de incorporação, fusão ou cisão em 90 dias da publicação; pagamento, garantia e falência produzem efeitos específicos.","A tutela protege crédito preexistente sem bloquear automaticamente a reorganização.","Credor demonstra prejuízo e ajuíza ação no prazo, mas sociedade garante dívida ilíquida e suspende o processo.","O prazo é decadencial e cada remédio depende de dívida líquida, ilíquida ou falência.","Consignação em pagamento","depósito judicial destinado a satisfazer obrigação e liberar o devedor"),
"1123": row("Sociedade que precisa de autorização executiva segue este título e lei especial; a competência autorizadora é sempre federal.","Certas atividades dependem de controle prévio da União, além das regras societárias comuns.","Empresa de setor legalmente condicionado pede autorização ao Poder Executivo federal.","A exigência deve resultar de lei; autorização não substitui registro e licenças próprias.","Autorização para funcionar","ato estatal prévio que permite atividade societária condicionada"),
"1124": row("Sem prazo diferente em lei ou ato público, autorização caduca se a sociedade não começar a funcionar em doze meses da publicação.","A permissão não fica indefinidamente disponível sem atividade efetiva.","Sociedade autorizada permanece inativa por um ano e perde a autorização.","Prazo especial expresso prevalece sobre os doze meses supletivos.","Caducidade","perda de eficácia pelo não exercício dentro do prazo"),
"1125": row("Executivo pode cassar a qualquer tempo autorização de sociedade nacional ou estrangeira que viole ordem pública ou atue contra seus fins estatutários.","O funcionamento autorizado continua sujeito à legalidade e ao objeto declarado.","Sociedade usa autorização para atividade contrária ao estatuto e sofre cassação.","Cassação exige fundamento legal e observância do procedimento administrativo aplicável.","Cassação","retirada da autorização por infração superveniente"),
"1126": row("É nacional a sociedade constituída segundo lei brasileira e com administração sediada no país; exigências de nacionalidade de sócios geram formalidades adicionais.","Nacionalidade societária combina ordenamento de constituição e localização da direção.","Sociedade registrada sob lei brasileira mantém sede administrativa em São Paulo.","Origem do capital, isoladamente, não substitui os dois critérios legais.","Sede da administração","local de direção efetiva da sociedade"),
"1127": row("Mudar a nacionalidade de sociedade brasileira exige consentimento unânime dos sócios ou acionistas.","A alteração fundamental não pode ser imposta pela maioria.","Todos os acionistas aprovam transferência que modifica a nacionalidade societária.","A unanimidade não dispensa autorizações e formalidades dos ordenamentos envolvidos.","Nacionalidade societária","vínculo jurídico da sociedade com determinado Estado"),
"1128": row("Pedido de autorização de sociedade nacional leva contrato assinado ou documentos da companhia autenticados; escritura pública pode ser comprovada por certidão.","O Executivo recebe prova íntegra e regular da constituição proposta.","Fundadores de companhia juntam estatuto e documentos exigidos pela lei especial.","A documentação varia conforme o tipo e a forma do ato constitutivo.","Certidão","documento público que reproduz ou comprova ato registrado"),
"1129": row("Executivo pode exigir alterações no contrato ou estatuto; sócios ou fundadores devem cumprir formalidades de revisão e provar sua regularidade.","A autorização pode ser condicionada à adequação do ato constitutivo.","Órgão pede ajuste de cláusula e a sociedade apresenta deliberação e registro correspondentes.","A exigência deve caber nos poderes legais e não autoriza mudança informal do contrato.","Aditamento","acréscimo formal a contrato ou estatuto"),
"1130": row("Executivo pode negar autorização se faltarem condições econômicas, financeiras ou jurídicas previstas em lei.","A decisão deve confrontar requisitos legais objetivos da atividade autorizada.","Pedido é recusado por capital mínimo legal não comprovado.","Não basta critério inventado fora da lei; a decisão administrativa está sujeita a controle.","Condição jurídica","requisito normativo para autorização válida"),
"1131": row("Após decreto autorizador, sociedade publica atos constitutivos e alterações em 30 dias no órgão oficial, usa exemplar para inscrição e também publica o termo registral em igual prazo.","Autorização, publicidade e registro são fases encadeadas.","Empresa publica decreto e contrato, registra-se e publica o termo de inscrição.","Os dois prazos de trinta dias têm fatos iniciais e objetos distintos.","Decreto de autorização","ato do Executivo que permite o funcionamento condicionado"),
"1132": row("Companhia nacional sujeita a autorização não pode constituir-se por subscrição pública antes de obtê-la; fundadores juntam projeto de estatuto e prospecto e depois registram os atos.","Captação pública exige controle estatal anterior à constituição.","Fundadores pedem autorização com prospecto antes de oferecer ações ao público.","Além do Código, incidem lei societária e regras do mercado de capitais.","Subscrição pública","formação de capital mediante oferta de ações ao público"),
"1133": row("Alterações contratuais ou estatutárias de sociedade autorizada precisam de aprovação, salvo aumento de capital com reservas ou reavaliação do ativo.","O controle estatal acompanha mudanças relevantes, com exceção patrimonial delimitada.","Sociedade pede aprovação para mudar objeto, mas usa reserva para aumentar capital sem essa aprovação específica.","A exceção não afasta deliberação, registro e demais requisitos legais.","Reavaliação do ativo","atualização formal do valor contábil de bens"),
"1134": row("Sociedade estrangeira só funciona no Brasil com autorização, inclusive por filial, embora possa ser acionista de companhia brasileira; o pedido exige documentos, tradução e prova de representação.","Atividade direta no país depende de controle e documentação abrangentes.","Empresa estrangeira pede autorização e apresenta estatuto, administradores, balanço e representante no Brasil.","Ser acionista não equivale a operar diretamente; leis especiais podem impor restrições adicionais.","Sociedade estrangeira","pessoa jurídica constituída sob lei de outro país"),
"1135": row("Executivo pode impor condições para proteger interesses nacionais; aceitas, decreto fixa autorização e capital destinado ao Brasil, seguido das publicações legais.","A autorização pode ser condicionada e delimitar recursos das operações nacionais.","Empresa aceita capital mínimo para filial e publica decreto e documentos.","Condições devem ser formalmente aceitas e compatíveis com a lei.","Capital destinado","parcela patrimonial alocada às operações no país"),
"1136": row("Sociedade estrangeira só inicia após inscrição local, instruída com publicações e depósito do capital; o registro especial contém dados e alterações de filiais também são averbadas.","Autorização federal não basta sem registro e comprovação patrimonial no local de atuação.","Filial deposita capital, arquiva documentos e só então começa a operar.","Cada estabelecimento e mudança relevante seguem publicidade e averbação exigidas.","Inscrição local","registro da sociedade estrangeira no lugar de seu estabelecimento"),
"1137": row("Sociedade estrangeira autorizada submete atos praticados no Brasil às leis e tribunais brasileiros e usa seu nome de origem, podendo adicionar referência ao Brasil.","Operações nacionais não escapam da jurisdição brasileira.","Contrato celebrado pela filial é julgado no Brasil conforme lei aplicável.","A regra alcança atos e operações no país, sem redefinir toda a situação global da sociedade.","Jurisdição brasileira","poder dos tribunais nacionais para decidir controvérsias"),
"1138": row("Sociedade estrangeira deve manter representante permanente no Brasil com poderes para resolver questões e receber citações; ele só atua perante terceiros após arquivamento e averbação.","A representação garante interlocução e acesso à Justiça no país.","Filial nomeia representante capaz de receber citação e registra a procuração.","Poderes devem ser suficientes e a publicidade registral antecede eficácia externa.","Receber citação","aceitar formalmente a comunicação de processo judicial"),
"1139": row("Mudança no contrato ou estatuto estrangeiro só produz efeitos no Brasil após aprovação do Executivo.","Alterações no país de origem precisam de controle nacional para repercutir localmente.","Matriz altera estatuto e solicita aprovação antes de aplicá-lo à filial brasileira.","Validade no exterior não implica automaticamente eficácia em território brasileiro.","Eficácia territorial","produção de efeitos jurídicos dentro de determinado país"),
"1140": row("Sociedade estrangeira deve republicar no Brasil divulgações obrigatórias de seu país e balanços das unidades brasileiras, sob pena de cassação.","A autorização exige transparência contínua sobre matriz e operações locais.","Filial publica balanço brasileiro e reproduz comunicação anual exigida no exterior.","Devem ser observados órgãos oficiais, periodicidade e demonstrações exigidas.","Publicidade societária","divulgação legal de atos e demonstrações da sociedade"),
"1141": row("Sociedade estrangeira pode nacionalizar-se com autorização, transferindo sede ao Brasil e apresentando documentos, capital realizado e deliberação; o Executivo pode impor condições.","A nacionalização é procedimento formal de mudança do vínculo jurídico e administrativo.","Matriz decide transferir sede, comprova capital e obtém decreto de nacionalização.","A transferência depende de ato societário, documentação e autorização, não de simples mudança de endereço.","Nacionalização","conversão da sociedade estrangeira em sociedade nacional"),
"1142": row("Estabelecimento é o conjunto organizado de bens da empresa e não se confunde com o local físico ou virtual; endereço registral virtual segue os critérios legais.","A universalidade empresarial abrange elementos coordenados para a atividade, independentemente do espaço de operação.","Loja muda de endereço, mas conserva marca, estoque, contratos e organização do estabelecimento.","O estabelecimento não é a própria sociedade nem apenas o imóvel onde funciona.","Estabelecimento empresarial","complexo organizado de bens utilizado na atividade empresarial"),
"1143": row("O estabelecimento pode ser tratado como unidade em direitos e negócios compatíveis com sua natureza.","O conjunto organizado pode ser vendido, arrendado ou gravado sem negociar cada elemento isoladamente.","Empresário transfere o estabelecimento inteiro por um único contrato.","Direitos personalíssimos e elementos intransferíveis exigem análise específica.","Objeto unitário","conjunto tratado juridicamente como uma unidade negocial"),
"1144": row("Alienação, usufruto ou arrendamento do estabelecimento só alcança terceiros após averbação no registro empresarial e publicação oficial.","Publicidade dupla torna o negócio oponível externamente.","Comprador averba o trespasse e publica o contrato antes de invocá-lo contra credores.","Entre as partes podem existir efeitos anteriores, mas a regra trata da eficácia perante terceiros.","Trespasse","transferência do estabelecimento empresarial"),
"1145": row("Se o alienante ficar sem bens suficientes, a transferência depende de pagar credores ou obter consentimento expresso ou tácito após notificação por trinta dias.","A venda não pode esvaziar patrimônio em prejuízo do passivo.","Vendedor notifica credores e aguarda trinta dias sem oposição antes do trespasse.","É necessário avaliar suficiência patrimonial; silêncio só vale após notificação regular.","Consentimento tácito","anuência inferida do silêncio nas condições previstas em lei"),
"1146": row("Adquirente responde por débitos anteriores regularmente contabilizados; alienante continua solidário por um ano, contado da publicação para vencidos e do vencimento para os demais.","O trespasse transfere passivo escriturado e mantém garantia temporária do antigo titular.","Comprador assume dívida registrada e fornecedor cobra também o vendedor dentro do prazo.","Dívidas trabalhistas, tributárias e outras podem seguir leis especiais próprias.","Débito contabilizado","obrigação registrada regularmente na escrituração empresarial"),
"1147": row("Sem autorização expressa, alienante não concorre com adquirente por cinco anos; em arrendamento ou usufruto, a vedação dura o contrato.","A regra protege a clientela e o valor transferido, admitindo ajuste expresso.","Vendedor de restaurante evita abrir concorrente próximo durante cinco anos.","A aplicação deve respeitar limites legítimos de atividade, tempo e espaço e o negócio celebrado.","Não concorrência","obrigação de não disputar a atividade transferida nas condições legais"),
"1148": row("Transferência sub-roga adquirente em contratos de exploração não pessoais, salvo cláusula contrária; terceiro pode rescindir por justa causa em noventa dias da publicação, com responsabilidade do alienante.","Contratos funcionais acompanham o estabelecimento, preservada reação do parceiro diante de motivo relevante.","Locação de equipamento operacional passa ao comprador, mas fornecedor rescinde por justa causa no prazo.","Contratos personalíssimos não se transferem automaticamente e a justa causa precisa ser demonstrada.","Sub-rogação contratual","entrada de novo titular na posição contratual existente"),
"1149": row("Cessão de créditos do estabelecimento vale contra devedores desde a publicação da transferência, mas pagamento de boa-fé ao antigo titular libera o devedor.","A publicidade desloca a titularidade externa, protegendo quem desconhecia legitimamente a mudança.","Cliente paga ao vendedor antes de saber da publicação e pode ficar liberado se agiu de boa-fé.","Depois da publicidade conhecida, pagamento ao cedente pode não extinguir a dívida.","Cedente","titular anterior que transfere o crédito"),
"1150": row("Empresário e sociedade empresária registram-se na Junta Comercial; sociedade simples, no Registro Civil, seguindo normas empresariais se adotar tipo de sociedade empresária.","O órgão competente depende da natureza da sociedade, não apenas do formato escolhido.","Limitada simples registra-se no RCPJ e observa formalidades do tipo adotado.","Classificação como simples ou empresária deve ser feita pela atividade e regime legal.","Registro Público de Empresas Mercantis","sistema de registro empresarial administrado pelas Juntas Comerciais"),
"1151": row("Registro é pedido pelo obrigado ou, diante de omissão, por sócio ou interessado; documentos em 30 dias retroagem à data do ato, depois disso só produzem efeito da concessão, com responsabilidade pela demora.","O protocolo tempestivo preserva eficácia desde a assinatura e incentiva publicidade rápida.","Alteração assinada é levada à Junta em vinte dias e produz efeitos desde o ato.","Após trinta dias, não há retroatividade registral e responsáveis podem responder por prejuízos.","Efeito retroativo","produção de efeitos desde data anterior à concessão do registro"),
"1152": row("Órgão registral verifica publicações legais; em regra elas ocorrem em órgão oficial e jornal de grande circulação, com disciplina própria para estrangeiras, e o anúncio informa onde o texto completo pode ser consultado.","A publicidade deve ser regular, verificável e adequada à sede e ao tipo de sociedade.","Sociedade publica aviso com referência ao registro que guarda a íntegra do documento.","Exceções legais e regras atuais de publicação devem ser conferidas para cada tipo societário.","Publicação oficial","divulgação em veículo indicado pela lei para dar publicidade ao ato"),
"1153": row("Antes do registro, autoridade confere autenticidade, legitimidade do requerente e requisitos legais, notificando irregularidades sanáveis.","O controle registral é de legalidade formal e permite correção antes da inscrição.","Junta identifica assinatura inválida e concede oportunidade para regularização.","Saneamento não transforma ato materialmente proibido em registrável.","Exigência registral","indicação formal de irregularidade que deve ser corrigida"),
"1154": row("Ato sujeito a registro não pode ser oposto a terceiro antes da formalidade, salvo prova de conhecimento; registrado, terceiro não alega desconhecimento.","A publicidade distribui o risco de informação sobre atos empresariais.","Alteração não registrada só vincula fornecedor se a sociedade provar que ele já a conhecia.","Regras especiais podem definir efeitos diferentes; o artigo trata da oponibilidade.","Oponibilidade","possibilidade de fazer um ato produzir efeitos contra terceiro"),
"1155": row("Nome empresarial é a firma ou denominação usada na empresa; a proteção também alcança denominações de sociedades simples, associações e fundações.","A lei protege sinais identificadores formais de diferentes pessoas jurídicas.","Associação impede uso registral conflitante com sua denominação protegida.","Nome empresarial não se confunde automaticamente com marca, domínio ou título de estabelecimento.","Nome empresarial","identificação jurídica adotada para o exercício da atividade"),
"1156": row("Empresário individual usa firma formada por seu nome, completo ou abreviado, podendo acrescentar identificação pessoal ou da atividade.","A firma revela o titular e admite complemento descritivo.","Marina Alves registra 'M. Alves Serviços Técnicos'.","O complemento não pode ocultar o nome civil nem violar veracidade e novidade.","Firma individual","nome empresarial baseado no nome civil do empresário"),
"1157": row("Sociedade com sócios ilimitadamente responsáveis usa firma apenas com nomes deles, podendo acrescentar 'e companhia'; quem figura pelo nome responde solidária e ilimitadamente.","O nome comunica ao mercado quais pessoas assumem risco pessoal ampliado.","Firma contém nome de um comanditado e 'e companhia', sem incluir comanditário.","Inserir nome de quem não deveria figurar pode produzir responsabilidade pessoal prevista no artigo.","E companhia","expressão que indica a existência de outros sócios não nominados"),
"1158": row("Limitada pode usar firma ou denominação, sempre com 'limitada' ou 'Ltda.'; firma usa nome de sócio pessoa física, denominação pode indicar objeto, e omissão do sufixo responsabiliza administradores que a empregarem.","O marcador de limitação informa terceiros e sua falta gera consequência pessoal aos gestores.","Administradora assina contrato sem 'Ltda.' e pode responder solidária e ilimitadamente por esse uso.","A redação e regras registrais atuais devem ser observadas na composição da denominação.","Sufixo societário","expressão final que identifica o tipo jurídico no nome empresarial"),
"1159": row("A denominação da cooperativa deve conter a palavra 'cooperativa'.","O nome empresarial precisa revelar sua natureza cooperativista.","Entidade registra 'Cooperativa dos Produtores do Vale'.","O vocábulo obrigatório não substitui requisitos da legislação especial e do registro.","Denominação cooperativa","nome empresarial que identifica expressamente o tipo cooperativo"),
"1160": row("Companhia usa denominação com 'sociedade anônima' ou 'companhia', por extenso ou abreviado; pode indicar objeto e incluir nome de pessoa ligada ao êxito de sua formação.","A redação vigente flexibiliza menção ao objeto, mas mantém identificação do tipo acionário.","Empresa registra 'Horizonte Companhia', incluindo nome de fundador na denominação.","Devem ser respeitadas posição e uso das expressões segundo a lei especial e normas registrais.","Companhia","designação legal de sociedade anônima"),
"1161": row("Comandita por ações pode adotar denominação, em vez de firma, acrescida de 'comandita por ações', sendo facultativa a indicação do objeto.","O nome deve tornar visível o tipo societário especial.","Sociedade registra 'Aurora Comandita por Ações'.","A escolha da denominação não altera responsabilidade própria dos diretores.","Comandita por ações","sociedade acionária com diretores de responsabilidade especial"),
"1162": row("Sociedade em conta de participação não pode possuir firma nem denominação.","Por não se apresentar como pessoa jurídica externa autônoma, atua por meio do sócio ostensivo.","Empreendimento em conta de participação contrata clientes no nome do sócio ostensivo.","Nome informal do projeto não cria nome empresarial nem personalidade jurídica.","Sócio ostensivo","participante que atua em nome próprio perante terceiros"),
}

